-- Synthetic POC data only. Run only against the dedicated vdagent_dw_dev database.
BEGIN;
DO $guard$ BEGIN IF current_database() <> 'vdagent_dw_dev' THEN
  RAISE EXCEPTION 'Refusing to replace data in %', current_database();
END IF; END $guard$;
TRUNCATE dw.unit_diagnostic_causes, dw.dm_unit_friction_diagnostics, dw.fact_sales_channel_performance, dw.fact_unit_inventory_snapshot, dw.fact_sales_funnel_daily, dw.fact_unit_price_history, dw.fact_market_macro_monthly, dw.dim_secondary_market_comps, dw.dim_sales_channel, dw.dim_unit_master, dw.dim_zone_master, dw.dim_project_profile, dw.dim_infrastructure_assets, dw.dim_date, dw.semantic_config, dw.snapshot_manifest RESTART IDENTITY CASCADE;
COPY dw.snapshot_manifest (snapshot_id, dataset_id, dataset_version, semantic_version, snapshot_date, timezone, currency, price_basis, area_basis, source_system) FROM '/tmp/vhsc_seed/snapshot_manifest.csv' WITH (FORMAT csv, HEADER true);
COPY dw.semantic_config (config_key, config_value, value_type, semantic_version, approval_status, description) FROM '/tmp/vhsc_seed/semantic_config.csv' WITH (FORMAT csv, HEADER true);
COPY dw.dim_date (date_key, full_date, year, quarter, month, day_of_month, is_weekend, fiscal_quarter) FROM '/tmp/vhsc_seed/dim_date.csv' WITH (FORMAT csv, HEADER true);
COPY dw.dim_infrastructure_assets (infra_key, infra_id, infra_name, infra_type, lifecycle_stage, construction_progress_pct, original_completion_year, revised_completion_year) FROM '/tmp/vhsc_seed/dim_infrastructure_assets.csv' WITH (FORMAT csv, HEADER true);
COPY dw.dim_project_profile (project_key, project_id, project_name, market_id, market_name, province_city, district, developer_name, developer_tier, developer_origin, segment, construction_status, construction_progress_pct, is_sales_permit_issued, is_bank_guarantee_issued, max_foreign_quota_exceeded, primary_infra_id, distance_to_primary_infra_m, partner_bank_name, expected_handover_date) FROM '/tmp/vhsc_seed/dim_project_profile.csv' WITH (FORMAT csv, HEADER true);
COPY dw.dim_zone_master (zone_key, zone_id, project_key, zone_name, zone_type, total_floors, basement_floors, units_per_floor, passenger_elevators, elevator_ratio, handover_standard) FROM '/tmp/vhsc_seed/dim_zone_master.csv' WITH (FORMAT csv, HEADER true);
COPY dw.dim_unit_master (unit_key, unit_id, unit_code, project_key, zone_key, unit_type, bedroom_count, bathroom_count, net_area_m2, gross_area_m2, floor_number, floor_band, balcony_orientation, door_orientation, view_primary_type, is_corner_unit, efficiency_ratio, distance_to_trash_room_m, is_adjacent_elevator, dark_bedroom_count, west_facing_exposure_pct, view_obstruction_distance_m, taboo_view_type, is_taboo_floor, ext_attributes) FROM '/tmp/vhsc_seed/dim_unit_master.csv' WITH (FORMAT csv, HEADER true);
COPY dw.dim_sales_channel (channel_key, channel_id, channel_name, channel_tier, active_brokers_count) FROM '/tmp/vhsc_seed/dim_sales_channel.csv' WITH (FORMAT csv, HEADER true);
COPY dw.dim_secondary_market_comps (comp_id, project_id, unit_type, floor_band, balcony_orientation, recorded_resale_date, resale_price_per_m2_vnd, pink_book_status) FROM '/tmp/vhsc_seed/dim_secondary_market_comps.csv' WITH (FORMAT csv, HEADER true);
COPY dw.fact_market_macro_monthly (macro_record_id, date_key, market_id, segment, floating_mortgage_rate_pct, months_of_inventory_moi, absorption_rate_pct, median_household_income_vnd, macro_price_to_income_ratio) FROM '/tmp/vhsc_seed/fact_market_macro_monthly.csv' WITH (FORMAT csv, HEADER true);
COPY dw.fact_unit_price_history (price_event_id, unit_key, effective_date_key, old_asking_price_vnd, new_asking_price_vnd, price_change_pct, change_reason) FROM '/tmp/vhsc_seed/fact_unit_price_history.csv' WITH (FORMAT csv, HEADER true);
COPY dw.fact_sales_funnel_daily (funnel_event_id, date_key, unit_key, web_listing_views, inquiry_leads_count, site_visits_count, booking_reservations, booking_cancellations, cancellation_reason) FROM '/tmp/vhsc_seed/fact_sales_funnel_daily.csv' WITH (FORMAT csv, HEADER true);
COPY dw.fact_unit_inventory_snapshot (snapshot_date_key, unit_key, project_key, zone_key, channel_key, launch_batch_id, release_date, inventory_status, sold_date, unsold_days_dom, is_overdue_flag, asking_price_vnd, discount_pct, concession_value_vnd, net_price_vnd, asking_price_per_m2, net_price_per_m2, subsidy_duration_mo, principal_grace_mo, base_commission_pct, spiff_bonus_vnd, is_exclusive_lock) FROM '/tmp/vhsc_seed/fact_unit_inventory_snapshot.csv' WITH (FORMAT csv, HEADER true);
COPY dw.fact_sales_channel_performance (snapshot_date_key, channel_key, project_key, assigned_units_count, sold_units_count, absorption_rate_pct, avg_days_to_sell, locked_inventory_over_90d) FROM '/tmp/vhsc_seed/fact_sales_channel_performance.csv' WITH (FORMAT csv, HEADER true);
COPY dw.dm_unit_friction_diagnostics (diagnostic_id, snapshot_date_key, unit_key, unit_code, project_name, zone_name, unsold_days_dom, price_spread_vs_peer_pct, ticket_size_vs_income_ratio, physical_defect_penalty, thermal_view_penalty, secondary_price_gap_pct, funnel_dropoff_rate_pct, primary_cause_code, recommended_action) FROM '/tmp/vhsc_seed/dm_unit_friction_diagnostics.csv' WITH (FORMAT csv, HEADER true);
COPY dw.unit_diagnostic_causes (diagnostic_id, cause_code, unit_key, snapshot_date_key, severity_rank, attribution_score, evidence_artifact_id) FROM '/tmp/vhsc_seed/unit_diagnostic_causes.csv' WITH (FORMAT csv, HEADER true);
COMMIT;
